/**
 * Service worker registration and the connection indicator.
 *
 * The service worker is generated by vite-plugin-pwa (see vite.config.js) and
 * precaches the built shell, the icons and the translation bundles. Because
 * inference runs on the device, a farmer who has installed the app can take a
 * photo and get a reading with no connection at all.
 *
 * The indicator restores the online/offline badge the single-screen build
 * showed, using the `status.online` / `status.offline` keys already present in
 * the locale files.
 */

import { registerSW } from "virtual:pwa-register";
import { t } from "./i18n.js";

export function registerServiceWorker() {
  // In the Android app (Capacitor) the shell already ships inside the APK, so a
  // service worker adds nothing and could serve a stale shell after an update.
  // Remove one left by an earlier build, then reload once so this build's
  // files are the ones on screen.
  if (window.Capacitor?.isNativePlatform?.()) {
    navigator.serviceWorker?.getRegistrations().then(async (registrations) => {
      if (!registrations.length) return;
      await Promise.all(registrations.map((registration) => registration.unregister()));
      window.location.reload();
    });
    return;
  }

  // `autoUpdate` in vite.config.js means a new build takes over on the next
  // load; nothing to prompt the farmer about.
  registerSW({ immediate: true });
}

export function mountConnectionIndicator() {
  const bar = document.createElement("p");
  bar.className = "ag-offline";
  bar.setAttribute("role", "status");
  document.body.append(bar);

  const update = () => {
    const offline = !navigator.onLine;
    bar.textContent = offline ? t("status.offline") : t("status.online");
    bar.dataset.offline = String(offline);
  };

  window.addEventListener("online", update);
  window.addEventListener("offline", update);
  update();
}
